import { setContext, getContext } from "svelte";
import { getNiceTicks } from "#lib/components/ui/chart/utils.js";
import { getBollinger, getEma, getSma, getVwap } from "./indicators.js";
import { formatFullTime, getTimeTicks, getZonedTime, isInWindow, isIntraday, parseClock, toTimestamp } from "./time.js";
import type { IndicatorSeries } from "./indicators.js";
import type { Candle, Indicator, IndicatorValue, PriceLevel, Props, TimeHighlight, TradingSession } from "./index.js";

const CONTEXT_ID = "candlestick-chart-context";
// Space in pixels between the plot and its labels, and around a tag's text.
const TICK_PADDING = 8;
const TAG_PADDING = 5;
// Fewest candles a zoom shows, so candles never grow past readable.
const MIN_VISIBLE = 10;
// Candle spacing in pixels of the default view.
const DEFAULT_SPACING = 8;
// Space between the price and volume panes, and the volume pane's share of the height.
const PANE_GAP = 8;
const VOLUME_SHARE = 0.2;
// Pixels each price tick needs, and the space each time label needs beyond its text.
const PIXELS_PER_PRICE_TICK = 48;
const TIME_LABEL_GAP = 24;
// Widest a candle body gets, and its share of the candle spacing.
const MAX_BODY_WIDTH = 12;
const BODY_SHARE = 0.7;
// Indicator colors in order; they skip the rising and falling hues, and later ones fall back to a neutral.
const INDICATOR_COLORS = ["var(--chart-1)", "var(--chart-4)", "var(--chart-5)"];
const FALLBACK_COLOR = "var(--muted-foreground)";
// Rising and falling colors; users override them with `--candlestick-chart-up` and `--candlestick-chart-down`.
export const UP_COLOR = "var(--candlestick-chart-up, var(--chart-3))";
export const DOWN_COLOR = "var(--candlestick-chart-down, var(--destructive))";
const priceFormat = new Intl.NumberFormat(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const compactFormat = new Intl.NumberFormat(undefined, { notation: "compact", maximumFractionDigits: 1 });

class UseCompCtx {
	/** Candles in time order */
	data: Candle[] = $state([]);
	/** Horizontal price lines */
	levels: PriceLevel[] = $state([]);
	/** Indicator settings */
	indicators: Indicator[] = $state([]);
	/** Daily clock windows shaded behind the candles */
	sessions: TradingSession[] = $state([]);
	/** Fixed time ranges shaded behind the candles */
	highlights: TimeHighlight[] = $state([]);
	/** IANA time zone; empty uses the viewer's zone */
	timeZone = $state("");
	/** Price scale */
	scale: NonNullable<Props["scale"]> = $state("linear");
	/** Whether the gridlines show */
	grid = $state(true);
	/** Whether the latest close gets a line and tag */
	lastPrice = $state(true);
	/** Whether the volume pane shows */
	showVolume = $state(true);
	/** Visible range set by zooming and panning; null shows the latest candles that fit */
	range: [number, number] | null = $state(null);
	/** Labels of the indicators hidden with the legend */
	hidden: string[] = $state([]);
	/** Body style */
	variant: NonNullable<Props["variant"]> = $state("solid");
	/** Custom price format */
	formatPrice?: Props["formatPrice"] = $state();
	/** Custom time format */
	formatTime?: Props["formatTime"] = $state();
	/** Custom volume format */
	formatVolume?: Props["formatVolume"] = $state();
	/** Custom tooltip content */
	tooltip?: Props["tooltip"] = $state();
	/** Called with the visible range */
	onRangeChange?: Props["onRangeChange"];
	/** Called with the hidden indicator labels */
	onHiddenIndicatorsChange?: Props["onHiddenIndicatorsChange"];
	/** Plot width in pixels */
	width = $state(0);
	/** Plot height in pixels */
	height = $state(0);
	/** Axis text size in pixels, read from CSS */
	fontSize = $state(12);
	/** Index of the hovered or focused candle; -1 while none is */
	activeIndex = $state(-1);
	/** Pointer position in plot pixels; null while the keyboard drives the tooltip */
	pointer: { x: number; y: number } | null = $state(null);
	/** Whether a drag or pinch is moving the chart */
	isDragging = $state(false);

	/** Timestamp of every candle */
	times = $derived(this.data.map((candle) => toTimestamp(candle.time)));
	/** Time zone for `Intl`, or undefined for the viewer's zone */
	zone = $derived(this.timeZone || undefined);
	/** Calendar fields of every candle in the time zone */
	zoned = $derived(this.times.map((time) => getZonedTime(time, this.zone)));
	/** Session windows in minutes since midnight */
	sessionWindows = $derived(this.sessions.map((session) => [parseClock(session.start), parseClock(session.end)]));
	/** Index of the session each candle falls in; -1 for regular hours */
	candleSessions = $derived(this.zoned.map((zoned) => this.sessionWindows.findIndex(([start, end]) => isInWindow(zoned.minuteOfDay, start, end))));
	/** Index of the highlight each candle falls in; -1 when none */
	candleHighlights = $derived.by(() => {
		const ranges = this.highlights.map((highlight) => [toTimestamp(highlight.start), toTimestamp(highlight.end)]);
		return this.times.map((time) => ranges.findIndex(([start, end]) => time >= start && time < end));
	});
	/** Close of every candle */
	closes = $derived(this.data.map((candle) => candle.close));
	/** Whether candles are less than a day apart */
	intraday = $derived(isIntraday(this.times));
	/** Every indicator computed over all the candles */
	series: IndicatorSeries[] = $derived(this.indicators.map((indicator, position) => this.buildSeries(indicator, position)));
	/** Indicators still shown */
	visibleSeries = $derived(this.series.filter((item) => !this.hidden.includes(item.label)));
	/** Pixels above the plot; leaves room for half of the top price label */
	marginTop = $derived(Math.ceil(this.fontSize / 2) + 4);
	/** Pixels left of the plot */
	marginLeft = 0;
	/** Pixels right of the plot for the price axis, sized for the widest price in the data so zooming never shifts it */
	marginRight = $derived(this.measureText([...this.data.flatMap((candle) => [candle.high, candle.low]), ...this.levels.map((level) => level.price), 0].map((price) => `▲ ${this.formatPriceValue(price)}`)) + TICK_PADDING * 2 + this.fontSize / 2);
	/** Height of the time axis under the plot */
	timeAxisHeight = $derived(Math.ceil(this.fontSize * 1.5) + TICK_PADDING);
	/** Width of the plot */
	plotWidth = $derived(Math.max(0, this.width - this.marginLeft - this.marginRight));
	/** Height of both panes together */
	panesHeight = $derived(Math.max(0, this.height - this.marginTop - this.timeAxisHeight));
	/** Height of the volume pane; 0 when it is hidden */
	volumeHeight = $derived(this.showVolume ? Math.round(this.panesHeight * VOLUME_SHARE) : 0);
	/** Height of the price pane */
	priceHeight = $derived(Math.max(0, this.panesHeight - this.volumeHeight - (this.showVolume ? PANE_GAP : 0)));
	/** Top of the volume pane */
	volumeTop = $derived(this.marginTop + this.priceHeight + PANE_GAP);
	/** Bottom of both panes, where the time axis starts */
	plotBottom = $derived(this.marginTop + this.panesHeight);
	/** Latest candles that fit at the default spacing */
	defaultRange: [number, number] = $derived.by(() => {
		const total = this.data.length;
		const count = Math.min(total, Math.max(MIN_VISIBLE, Math.floor(this.plotWidth / DEFAULT_SPACING)));
		return [total - count, total];
	});
	/** Visible range, as fractional candle indexes */
	view = $derived(this.range ?? this.defaultRange);
	/** Number of candles across the plot */
	visibleCount = $derived(Math.max(1, this.view[1] - this.view[0]));
	/** Pixels between candle centers */
	spacing = $derived(this.plotWidth / this.visibleCount);
	/** Width of a candle body */
	bodyWidth = $derived(Math.max(1, Math.min(MAX_BODY_WIDTH, this.spacing * BODY_SHARE)));
	/** Indexes of the candles at least partly on screen */
	visibleIndexes = $derived.by(() => {
		const first = Math.max(0, Math.floor(this.view[0]));
		const last = Math.min(this.data.length - 1, Math.ceil(this.view[1]) - 1);
		return Array.from({ length: Math.max(0, last - first + 1) }, (_, offset) => first + offset);
	});
	/** Every price on screen: candles and visible indicators */
	visiblePrices = $derived(this.visibleIndexes.flatMap((index) => [this.data[index].low, this.data[index].high, ...this.visibleSeries.flatMap((item) => [item.line[index], ...item.bands.flatMap((band) => [band.upper[index], band.lower[index]])])]).filter(Number.isFinite));
	/** Whether the price axis is logarithmic; it falls back to linear when a price on screen is zero or below */
	isLog = $derived(this.scale === "log" && this.visiblePrices.every((price) => price > 0));
	/** Lowest and highest price on screen, padded so wicks never touch the edges; levels do not stretch it */
	priceDomain = $derived.by(() => {
		const min = this.visiblePrices.length ? this.toScale(Math.min(...this.visiblePrices)) : 0;
		const max = this.visiblePrices.length ? this.toScale(Math.max(...this.visiblePrices)) : 1;
		// Pad in scale units, so a log axis pads by the same share at both ends.
		const padding = (max - min) * 0.06 || Math.abs(max) * 0.01 || 1;
		return [this.fromScale(min - padding), this.fromScale(max + padding)];
	});
	/** Price ticks inside the domain: round numbers, spaced evenly in log units on a log axis and rounded to 2 significant digits */
	priceTicks = $derived.by(() => {
		const [min, max] = this.priceDomain;
		const count = Math.max(2, Math.floor(this.priceHeight / PIXELS_PER_PRICE_TICK));
		const ticks = this.isLog ? [...new Set(getNiceTicks(Math.log(min), Math.log(max), count).map((tick) => Number(Math.exp(tick).toPrecision(2))))] : getNiceTicks(min, max, count);
		return ticks.filter((tick) => tick >= min && tick <= max);
	});
	/** Highest volume on screen */
	maxVolume = $derived(Math.max(1, ...this.visibleIndexes.map((index) => this.data[index].volume ?? 0)));
	/** Height of a tag on an axis */
	tagHeight = $derived(this.fontSize + TAG_PADDING);
	/** Height of the crosshair's horizontal line: the pointer inside the price pane, else the active candle's close */
	crosshairY = $derived.by(() => {
		const candle = this.data[this.activeIndex];
		if (this.pointer && this.pointer.y >= this.marginTop && this.pointer.y <= this.marginTop + this.priceHeight) return this.pointer.y;
		return candle ? this.priceToY(candle.close) : 0;
	});
	/** Time tag under the crosshair, kept inside the plot; null while no candle is active */
	timeTag = $derived.by(() => {
		// If no candle is active: there is no tag.
		if (!this.data[this.activeIndex]) return null;
		const text = this.formatCandleTime(this.activeIndex);
		const width = this.measureText([text]) + TAG_PADDING * 2;
		const x = Math.min(Math.max(this.x(this.activeIndex) - width / 2, this.marginLeft), this.marginLeft + this.plotWidth - width);
		return { text, x, width };
	});
	/** Every level and the last price, placed on the price axis; tags that would overlap stack apart while their lines stay at their prices */
	levelTags = $derived.by(() => {
		const [min, max] = this.priceDomain;
		const last = this.data.at(-1);
		// The latest close joins the levels in its direction's color, so live updates show where price is now.
		const lastLevel: PriceLevel[] = this.lastPrice && last ? [{ price: last.close, kind: last.close >= last.open ? "support" : "resistance" }] : [];
		const tags = [...this.levels, ...lastLevel].map((level, position) => {
			// Levels off screen pin to the nearest edge with an arrow toward them.
			const placement = level.price > max ? "above" : level.price < min ? "below" : "inside";
			const lineY = placement === "above" ? this.marginTop + this.tagHeight / 2 : placement === "below" ? this.marginTop + this.priceHeight - this.tagHeight / 2 : this.priceToY(level.price);
			const text = `${placement === "above" ? "▲ " : placement === "below" ? "▼ " : ""}${this.formatPriceValue(level.price)}`;
			return { ...level, position, placement, lineY, tagY: lineY, text, color: this.levelColor(level), isLast: position >= this.levels.length };
		});
		// Walk the tags from top to bottom and push each one below the tag above it when they would overlap.
		const sorted = tags.toSorted((a, b) => a.lineY - b.lineY);
		for (const [index, tag] of sorted.entries()) {
			const above = sorted[index - 1];
			if (above && tag.tagY - above.tagY < this.tagHeight) tag.tagY = above.tagY + this.tagHeight;
		}
		return tags;
	});
	/** Heights of the tags on the price axis: the crosshair's, the last price's, and every level's */
	priceTagYs = $derived([...(this.timeTag ? [this.crosshairY] : []), ...this.levelTags.map((tag) => tag.tagY)]);
	/** Time ticks on calendar boundaries, spaced so labels never overlap */
	timeTicks = $derived.by(() => {
		const minGap = this.measureText([this.intraday ? "00:00" : "Sep 30"]) + TIME_LABEL_GAP;
		let lastX = -Infinity;
		return getTimeTicks(this.times, this.zoned, this.visibleIndexes, this.plotWidth, minGap, this.zone).filter(({ index }) => {
			const x = this.x(index);
			// If the tick crowds the one before it: skip it.
			if (x - lastX < minGap) return false;
			lastX = x;
			return true;
		});
	});

	// Set default data
	constructor(props: { [key: string]: any }) {
		// Merge props into this instance (we do not use `Object.assign(this, props)` to ensure only setting props that exists)
		for (const [key, data] of Object.entries(props)) {
			// @ts-ignore
			if (this[key] !== undefined) this[key] = data;
		}
	}

	/** Computes one indicator over all the candles. */
	buildSeries(indicator: Indicator, position: number): IndicatorSeries {
		const color = indicator.color ?? INDICATOR_COLORS[position] ?? FALLBACK_COLOR;
		if (indicator.type === "bollinger") {
			const period = indicator.period ?? 20;
			const deviations = indicator.deviations ?? 2;
			const { middle, band } = getBollinger(this.closes, period, deviations);
			return { label: indicator.label ?? `BB ${period}, ${deviations}`, color, line: middle, bands: [band], breaks: [] };
		}
		if (indicator.type === "vwap") {
			// A daily reset follows the calendar date in the chart's time zone.
			const sessionKeys = indicator.reset === "none" ? this.times.map(() => 0) : this.zoned.map((zoned) => zoned.dayNumber);
			const include = indicator.regularHours ? this.candleSessions.map((session) => session < 0) : undefined;
			const { line, bands, sessionStarts } = getVwap(this.data, sessionKeys, indicator.bands ?? [], include);
			return { label: indicator.label ?? "VWAP", color, line, bands, breaks: sessionStarts };
		}
		const line = indicator.type === "sma" ? getSma(this.closes, indicator.period) : getEma(this.closes, indicator.period);
		return { label: indicator.label ?? `${indicator.type.toUpperCase()} ${indicator.period}`, color, line, bands: [], breaks: [] };
	}

	/** Estimates the pixel width of the longest text, from the axis font size. */
	measureText(texts: string[]) {
		return Math.ceil(Math.max(0, ...texts.map((text) => text.length)) * this.fontSize * 0.6);
	}

	/** Formats a price. */
	formatPriceValue(price: number) {
		if (Number.isNaN(price)) return "–";
		return this.formatPrice ? this.formatPrice(price) : priceFormat.format(price);
	}

	/** Formats a volume; compact unless `formatVolume` is set. */
	formatVolumeValue(volume: number | undefined) {
		if (volume === undefined || Number.isNaN(volume)) return "–";
		return this.formatVolume ? this.formatVolume(volume) : compactFormat.format(volume);
	}

	/** Formats a candle's time in full. */
	formatCandleTime(index: number) {
		const time = this.times[index];
		// If the candle does not exist: show nothing.
		if (time === undefined) return "";
		return this.formatTime ? this.formatTime(new Date(time), index) : formatFullTime(time, this.intraday, this.zone);
	}

	/** Pixel center of a candle. */
	x(index: number) {
		return this.marginLeft + (index - this.view[0] + 0.5) * this.spacing;
	}

	/** Converts a price to scale units: its logarithm on a log axis. */
	toScale(price: number) {
		return this.isLog ? Math.log(price) : price;
	}

	/** Converts scale units back to a price. */
	fromScale(value: number) {
		return this.isLog ? Math.exp(value) : value;
	}

	/** Pixel position of a price in the price pane. */
	priceToY(price: number) {
		const min = this.toScale(this.priceDomain[0]);
		const max = this.toScale(this.priceDomain[1]);
		return this.marginTop + (1 - (this.toScale(price) - min) / (max - min || 1)) * this.priceHeight;
	}

	/** Price at a pixel position in the price pane. */
	yToPrice(y: number) {
		const min = this.toScale(this.priceDomain[0]);
		const max = this.toScale(this.priceDomain[1]);
		return this.fromScale(min + (1 - (y - this.marginTop) / (this.priceHeight || 1)) * (max - min));
	}

	/** Label of the highlight or session a candle falls in, such as "Pre-market". */
	getSessionLabel(index: number) {
		const highlight = this.highlights[this.candleHighlights[index]];
		return highlight?.label ?? this.sessions[this.candleSessions[index]]?.label;
	}

	/** Pixel position of a volume in the volume pane. */
	volumeToY(volume: number) {
		return this.volumeTop + (1 - volume / this.maxVolume) * this.volumeHeight;
	}

	/** Color of a level: its own, else rising for support, falling for resistance, and neutral otherwise. */
	levelColor(level: PriceLevel) {
		if (level.color) return level.color;
		if (level.kind === "support") return UP_COLOR;
		return level.kind === "resistance" ? DOWN_COLOR : FALLBACK_COLOR;
	}

	/** Change from the previous close, or from the open on the first candle. */
	getChange(index: number) {
		const candle = this.data[index];
		const previous = this.data[index - 1]?.close ?? candle.open;
		const change = candle.close - previous;
		return { change, changePercent: previous ? (change / previous) * 100 : 0 };
	}

	/** Values of the visible indicators at a candle. */
	getIndicatorValues(index: number): IndicatorValue[] {
		return this.visibleSeries.map((item) => ({ label: item.label, color: item.color, value: item.line[index], formattedValue: this.formatPriceValue(item.line[index]) }));
	}

	/** Finds the candle under a pointer, or -1 outside the plot. */
	indexAt(x: number) {
		// If the pointer is beside the plot, such as over the price axis: hover nothing.
		if (x < this.marginLeft || x > this.marginLeft + this.plotWidth || !this.visibleIndexes.length) return -1;
		const index = Math.floor(this.view[0] + (x - this.marginLeft) / (this.spacing || 1));
		return Math.min(this.visibleIndexes.at(-1) ?? 0, Math.max(this.visibleIndexes[0], index));
	}

	/** Shows `count` candles from `start`, clamped to the data, and reports the range. */
	setRange(start: number, count: number) {
		const total = this.data.length;
		// If there is no data: there is nothing to show.
		if (!total) return;
		const nextCount = Math.min(total, Math.max(Math.min(MIN_VISIBLE, total), count));
		const nextStart = Math.min(total - nextCount, Math.max(0, start));
		this.range = [nextStart, nextStart + nextCount];
		this.onRangeChange?.(this.range);
	}

	/** Zooms by `factor` around a pixel, keeping the candle under it in place; below 1 zooms in. */
	zoom(factor: number, anchorX: number) {
		const share = Math.min(1, Math.max(0, (anchorX - this.marginLeft) / (this.plotWidth || 1)));
		const anchorIndex = this.view[0] + share * this.visibleCount;
		const count = this.visibleCount * factor;
		this.setRange(anchorIndex - share * count, count);
	}

	/** Pans by a number of candles; positive moves toward newer candles. */
	pan(candles: number) {
		this.setRange(this.view[0] + candles, this.visibleCount);
	}

	/** Shows the latest candles again. */
	resetRange() {
		this.range = null;
		this.onRangeChange?.(this.defaultRange);
	}

	/** Activates a candle from the keyboard, panning to keep it on screen. */
	moveActive(index: number) {
		const target = Math.min(this.data.length - 1, Math.max(0, index));
		this.pointer = null;
		this.activeIndex = target;
		// If the candle is off screen: pan just enough to show it.
		if (target < this.view[0]) this.setRange(target, this.visibleCount);
		else if (target + 1 > this.view[1]) this.setRange(target + 1 - this.visibleCount, this.visibleCount);
	}

	/** Hides or shows an indicator and reports the change. */
	toggleIndicator(label: string) {
		this.hidden = this.hidden.includes(label) ? this.hidden.filter((hiddenLabel) => hiddenLabel !== label) : [...this.hidden, label];
		this.onHiddenIndicatorsChange?.(this.hidden);
	}
}

export type CompCtxProps = Pick<InstanceType<typeof UseCompCtx>, "data" | "levels" | "indicators" | "sessions" | "highlights" | "timeZone" | "scale" | "grid" | "lastPrice" | "showVolume" | "range" | "hidden" | "variant" | "formatPrice" | "formatTime" | "formatVolume" | "tooltip" | "onRangeChange" | "onHiddenIndicatorsChange">;

export const setCompCtx = (props: CompCtxProps) => setContext(CONTEXT_ID, new UseCompCtx(props));

export const useCompCtx = () => getContext<ReturnType<typeof setCompCtx>>(CONTEXT_ID);

export { default as CandlestickChart } from "./_.svelte";
export { getSma, getEma, getBollinger, getVwap } from "./indicators.js";

/** One period of trading: its open, high, low, close, and volume */
export interface Candle {
	/** Start of the period, as a `Date`, a timestamp in milliseconds, or a date string */
	time: Date | number | string;
	/** First price */
	open: number;
	/** Highest price */
	high: number;
	/** Lowest price */
	low: number;
	/** Last price */
	close: number;
	/** Traded volume; the volume pane and VWAP need it */
	volume?: number;
}

/** Horizontal price line, such as a support or resistance level */
export interface PriceLevel {
	/** Price of the line */
	price: number;
	/** Name drawn above the line, such as "Support" */
	label?: string;
	/** `support` uses the rising color, `resistance` the falling color, and `default` a neutral one */
	kind?: "support" | "resistance" | "default";
	/** Any CSS color; overrides the `kind` color */
	color?: string;
}

/** Daily clock window shaded behind the candles, such as pre-market or after hours */
export interface TradingSession {
	/** Start time as `HH:mm` in `timeZone`, such as `04:00` */
	start: string;
	/** End time as `HH:mm` in `timeZone`, not included, such as `09:30`; an end before the start runs past midnight */
	end: string;
	/** Name on the shading and in the tooltip, such as "Pre-market" */
	label: string;
	/** Any CSS color for the shading; defaults to `--muted-foreground` */
	color?: string;
}

/** Fixed time range shaded behind the candles, such as an earnings release */
export interface TimeHighlight {
	/** Start of the range, as a `Date`, a timestamp in milliseconds, or a date string */
	start: Date | number | string;
	/** End of the range, not included */
	end: Date | number | string;
	/** Name on the shading and in the tooltip */
	label?: string;
	/** Any CSS color for the shading; defaults to `--chart-4` */
	color?: string;
}

/** Simple or exponential moving average of the closes */
export interface MovingAverageIndicator {
	/** `sma` weighs every close in the window equally; `ema` weighs recent closes more */
	type: "sma" | "ema";
	/** Number of candles in the window, such as 20 */
	period: number;
	/** Name in the legend and tooltip; defaults to "SMA 20" or "EMA 20"; also the key in `hiddenIndicators` */
	label?: string;
	/** Any CSS color; defaults to the next indicator color */
	color?: string;
}

/** Bollinger bands around a simple moving average */
export interface BollingerIndicator {
	/** Bollinger bands */
	type: "bollinger";
	/** Number of candles in the window; defaults to 20 */
	period?: number;
	/** Standard deviations from the average to each band; defaults to 2 */
	deviations?: number;
	/** Name in the legend and tooltip; defaults to "BB 20, 2"; also the key in `hiddenIndicators` */
	label?: string;
	/** Any CSS color; defaults to the next indicator color */
	color?: string;
}

/** Volume-weighted average price */
export interface VwapIndicator {
	/** Volume-weighted average price */
	type: "vwap";
	/** `day` restarts the average at each local day; `none` runs it across all the data; defaults to `day` */
	reset?: "day" | "none";
	/** Standard deviation bands to draw, such as `[1, 2]`; none by default */
	bands?: number[];
	/** Skips candles inside `sessions`, such as pre-market and after hours, so the average covers regular hours only */
	regularHours?: boolean;
	/** Name in the legend and tooltip; defaults to "VWAP"; also the key in `hiddenIndicators` */
	label?: string;
	/** Any CSS color; defaults to the next indicator color */
	color?: string;
}

/** Overlay computed from the candles */
export type Indicator = MovingAverageIndicator | BollingerIndicator | VwapIndicator;

/** One indicator value a custom `tooltip` snippet receives */
export interface IndicatorValue {
	/** Indicator label */
	label: string;
	/** Indicator color */
	color: string;
	/** Raw value; `NaN` before the indicator has enough candles */
	value: number;
	/** Value after `formatPrice` */
	formattedValue: string;
}

/** Values a custom `tooltip` snippet receives */
export interface TooltipSnippetProps {
	/** Index of the hovered candle in `data` */
	index: number;
	/** Hovered candle */
	candle: Candle;
	/** Time after `formatTime` */
	label: string;
	/** Label of the session or highlight the candle falls in, such as "Pre-market" */
	session?: string;
	/** Change from the previous close, or from the open on the first candle */
	change: number;
	/** Change in percent */
	changePercent: number;
	/** Value of every visible indicator at this candle */
	indicators: IndicatorValue[];
}

/** Candlestick chart with sessions, a volume pane, indicators, price levels, live updates, zoom, and pan */
export interface Props extends CompProps<"figure"> {
	/** Candles in time order, oldest first */
	data: Candle[];
	/** Horizontal price lines, such as support and resistance */
	levels?: PriceLevel[];
	/** Overlays computed from the candles: moving averages, Bollinger bands, and VWAP */
	indicators?: Indicator[];
	/** Daily clock windows shaded behind the candles, such as pre-market and after hours */
	sessions?: TradingSession[];
	/** Fixed time ranges shaded behind the candles, such as earnings */
	highlights?: TimeHighlight[];
	/** IANA time zone for sessions, day resets, the time axis, and the tooltip, such as `America/New_York`; the viewer's zone when omitted */
	timeZone?: string;
	/** Shows the volume pane; on when any candle has volume */
	volume?: boolean;
	/** Visible candles as `[start, end)` indexes, fractional while panning; the latest candles that fit when omitted; supports `bind:range` */
	range?: [number, number];
	/** Called with the visible range when the chart zooms or pans */
	onRangeChange?: (range: [number, number]) => void;
	/** Labels of the indicators hidden with the legend; supports `bind:hiddenIndicators` */
	hiddenIndicators?: string[];
	/** Called with the hidden indicator labels when the legend hides or shows one */
	onHiddenIndicatorsChange?: (hiddenIndicators: string[]) => void;
	/** Price style: `solid` and `hollow` candles, where `hollow` leaves rising bodies empty, `ohlc` bars, or a `line` or `area` of the closes; defaults to `solid` */
	variant?: "solid" | "hollow" | "ohlc" | "line" | "area";
	/** Price scale; `log` spaces equal percent moves equally, for long ranges; defaults to `linear` */
	scale?: "linear" | "log";
	/** Draws the gridlines; defaults to `true` */
	grid?: boolean;
	/** Marks the latest close with a dotted line and an axis tag, which follows live updates; defaults to `true` */
	lastPrice?: boolean;
	/** Axis and legend text, and the plot height unless `--candlestick-chart-height` is set; defaults to `md` */
	size?: UiSize;
	/** Formats prices on the axis, tags, tooltip, and table */
	formatPrice?: (price: number) => string;
	/** Formats a candle's time in the tooltip, table, and announcements; axis ticks pick their own format by zoom level */
	formatTime?: (time: Date, index: number) => string;
	/** Formats volumes in the tooltip and table; compact numbers, such as 1.2K, when omitted */
	formatVolume?: (volume: number) => string;
	/** Custom tooltip content for the hovered candle */
	tooltip?: Snippet<[TooltipSnippetProps]>;
	/** Shows the indicator legend; on when there are indicators */
	legend?: boolean;
	/** Shows the table of visible candles under the chart; screen readers always get it */
	table?: boolean;
	/** Accessible name of the plot, such as "AAPL, 5 minute candles"; defaults to "Candlestick chart" */
	label?: string;
	/** Classes merged onto the chart */
	class?: CompProps<"figure">["class"];
}

export type CandlestickChartProps = Props;
export type CandlestickChartCandle = Candle;
export type CandlestickChartPriceLevel = PriceLevel;
export type CandlestickChartIndicator = Indicator;
export type CandlestickChartTradingSession = TradingSession;
export type CandlestickChartTimeHighlight = TimeHighlight;
export type CandlestickChartIndicatorValue = IndicatorValue;
export type CandlestickChartTooltipSnippetProps = TooltipSnippetProps;

/** Upper and lower edges of a band around an indicator line */
export interface IndicatorBand {
	/** Standard deviations from the line */
	deviations: number;
	/** Upper edge per candle; `NaN` where it is not defined yet */
	upper: number[];
	/** Lower edge per candle; `NaN` where it is not defined yet */
	lower: number[];
}

/** An indicator computed over every candle, ready to draw */
export interface IndicatorSeries {
	/** Name in the legend and tooltip, and the key in `hiddenIndicators` */
	label: string;
	/** CSS color of the line and bands */
	color: string;
	/** Main line per candle; `NaN` where it is not defined yet */
	line: number[];
	/** Bands around the line, such as Bollinger or VWAP deviation bands */
	bands: IndicatorBand[];
	/** Candle indexes where the line restarts, such as each new VWAP day, so it draws no jump there */
	breaks: number[];
}

/** Price fields the volume-weighted average reads */
interface VwapCandle {
	/** Highest price */
	high: number;
	/** Lowest price */
	low: number;
	/** Last price */
	close: number;
	/** Traded volume; candles without it add no weight */
	volume?: number;
}

/** Simple moving average; the first `period - 1` values are `NaN`, since the window is not full yet. */
export function getSma(values: number[], period: number) {
	const result = values.map(() => NaN);
	let sum = 0;
	for (const [index, value] of values.entries()) {
		sum += value;
		// If the window is full: drop the value that left it.
		if (index >= period) sum -= values[index - period];
		if (index >= period - 1) result[index] = sum / period;
	}
	return result;
}

/** Exponential moving average, seeded with the simple average of the first window. */
export function getEma(values: number[], period: number) {
	const smoothing = 2 / (period + 1);
	const seed = getSma(values, period);
	const result = values.map(() => NaN);
	for (let index = period - 1; index < values.length; index++) {
		const previous = result[index - 1];
		result[index] = Number.isNaN(previous) ? seed[index] : values[index] * smoothing + previous * (1 - smoothing);
	}
	return result;
}

/** Bollinger bands: a simple moving average with bands `deviations` population standard deviations away. */
export function getBollinger(values: number[], period: number, deviations: number) {
	const middle = getSma(values, period);
	const band: IndicatorBand = { deviations, upper: values.map(() => NaN), lower: values.map(() => NaN) };
	for (let index = period - 1; index < values.length; index++) {
		const window = values.slice(index - period + 1, index + 1);
		const spread = Math.sqrt(window.reduce((sum, value) => sum + (value - middle[index]) ** 2, 0) / period);
		band.upper[index] = middle[index] + deviations * spread;
		band.lower[index] = middle[index] - deviations * spread;
	}
	return { middle, band };
}

/** Volume-weighted average of the typical price `(high + low + close) / 3`, with volume-weighted deviation bands; it restarts whenever `sessionKeys` changes, such as at each day, and skips candles where `include` is false. */
export function getVwap(candles: VwapCandle[], sessionKeys: (number | string)[], bandDeviations: number[], include?: boolean[]) {
	const line = candles.map(() => NaN);
	const bands: IndicatorBand[] = bandDeviations.map((deviations) => ({ deviations, upper: candles.map(() => NaN), lower: candles.map(() => NaN) }));
	const sessionStarts: number[] = [];
	let session: number | string | undefined;
	let priceVolume = 0;
	let squaredPriceVolume = 0;
	let totalVolume = 0;
	for (const [index, candle] of candles.entries()) {
		// If the candle is left out, such as pre-market for a regular hours VWAP: it adds nothing and draws no line.
		if (include && !include[index]) continue;
		// If a new session started: restart the running sums.
		if (sessionKeys[index] !== session) {
			if (session !== undefined) sessionStarts.push(index);
			session = sessionKeys[index];
			priceVolume = 0;
			squaredPriceVolume = 0;
			totalVolume = 0;
		}
		const typicalPrice = (candle.high + candle.low + candle.close) / 3;
		const volume = Math.max(0, candle.volume ?? 0);
		priceVolume += typicalPrice * volume;
		squaredPriceVolume += typicalPrice * typicalPrice * volume;
		totalVolume += volume;
		// If no volume has traded this session: there is no average yet.
		if (!totalVolume) continue;
		line[index] = priceVolume / totalVolume;
		const spread = Math.sqrt(Math.max(0, squaredPriceVolume / totalVolume - line[index] ** 2));
		for (const band of bands) {
			band.upper[index] = line[index] + band.deviations * spread;
			band.lower[index] = line[index] - band.deviations * spread;
		}
	}
	return { line, bands, sessionStarts };
}

/** Calendar unit and step that time ticks fall on, such as every 15 minutes */
type TimeUnit = [kind: "minute" | "hour" | "day" | "month" | "year", step: number];

/** Calendar fields of a time in one time zone */
export interface ZonedTime {
	/** Full year */
	year: number;
	/** Month from 0 to 11 */
	month: number;
	/** Day of the month */
	day: number;
	/** Minutes since midnight */
	minuteOfDay: number;
	/** Days since 1970-01-01 for this calendar date, so dates compare across time zones */
	dayNumber: number;
}

/** Time formats for one time zone */
interface TimeFormats {
	/** Clock time, such as 09:30 AM */
	time: Intl.DateTimeFormat;
	/** Short date, such as Oct 21 */
	day: Intl.DateTimeFormat;
	/** Short month, such as Oct */
	month: Intl.DateTimeFormat;
	/** Year, such as 2026 */
	year: Intl.DateTimeFormat;
	/** Date and clock time for intraday candles */
	intraday: Intl.DateTimeFormat;
	/** Full date for daily candles */
	daily: Intl.DateTimeFormat;
	/** Calendar fields in numeric parts, read by `getZonedTime` */
	parts: Intl.DateTimeFormat;
}

// Tick units from finest to coarsest; the axis uses the finest one whose labels fit.
const TIME_UNITS: TimeUnit[] = [
	["minute", 1],
	["minute", 5],
	["minute", 15],
	["minute", 30],
	["hour", 1],
	["hour", 2],
	["hour", 4],
	["hour", 6],
	["hour", 12],
	["day", 1],
	["day", 2],
	["day", 7],
	["month", 1],
	["month", 3],
	["month", 6],
	["year", 1],
];
const DAY_MS = 86_400_000;
// Formats per time zone, built once; the empty key is the viewer's own zone.
const formatsByZone = new Map<string, TimeFormats>();

/** Returns the time formats for a time zone, building them on first use. */
function getFormats(timeZone: string | undefined) {
	const cached = formatsByZone.get(timeZone ?? "");
	// If the formats exist: reuse them, since building them is slow.
	if (cached) return cached;
	const formats: TimeFormats = {
		time: new Intl.DateTimeFormat(undefined, { timeZone, hour: "2-digit", minute: "2-digit" }),
		day: new Intl.DateTimeFormat(undefined, { timeZone, month: "short", day: "numeric" }),
		month: new Intl.DateTimeFormat(undefined, { timeZone, month: "short" }),
		year: new Intl.DateTimeFormat(undefined, { timeZone, year: "numeric" }),
		intraday: new Intl.DateTimeFormat(undefined, { timeZone, month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }),
		daily: new Intl.DateTimeFormat(undefined, { timeZone, year: "numeric", month: "short", day: "numeric" }),
		parts: new Intl.DateTimeFormat("en-US", { timeZone, year: "numeric", month: "numeric", day: "numeric", hour: "numeric", minute: "numeric", hourCycle: "h23" }),
	};
	formatsByZone.set(timeZone ?? "", formats);
	return formats;
}

/** Converts a candle time to a timestamp in milliseconds. */
export function toTimestamp(time: Date | number | string) {
	if (time instanceof Date) return time.getTime();
	return typeof time === "number" ? time : Date.parse(time);
}

/** Reads the calendar fields of a time in a time zone; the viewer's zone when `timeZone` is omitted. */
export function getZonedTime(time: number, timeZone?: string): ZonedTime {
	const parts = Object.fromEntries(
		getFormats(timeZone)
			.parts.formatToParts(time)
			.map((part) => [part.type, part.value]),
	);
	const year = Number(parts.year);
	const month = Number(parts.month) - 1;
	const day = Number(parts.day);
	return { year, month, day, minuteOfDay: (Number(parts.hour) % 24) * 60 + Number(parts.minute), dayNumber: Date.UTC(year, month, day) / DAY_MS };
}

/** Converts a clock time such as `09:30` to minutes since midnight. */
export function parseClock(clock: string) {
	const [hours = 0, minutes = 0] = clock.split(":").map(Number);
	return hours * 60 + minutes;
}

/** Whether minutes since midnight fall in a clock window; a window that ends before it starts runs past midnight. */
export function isInWindow(minuteOfDay: number, start: number, end: number) {
	return start <= end ? minuteOfDay >= start && minuteOfDay < end : minuteOfDay >= start || minuteOfDay < end;
}

/** Whether candles are less than a day apart, judged by the median gap so weekends do not count. */
export function isIntraday(times: number[]) {
	const gaps = times
		.slice(1)
		.map((time, index) => time - times[index])
		.toSorted((a, b) => a - b);
	return gaps.length > 0 && gaps[Math.floor(gaps.length / 2)] < DAY_MS;
}

/** Formats a candle time in full for the tooltip, table, and announcements. */
export function formatFullTime(time: number, intraday: boolean, timeZone?: string) {
	const formats = getFormats(timeZone);
	return (intraday ? formats.intraday : formats.daily).format(time);
}

/** Names the bucket a time falls in for a unit; a candle starting a new bucket gets a tick. */
function getBucket(zoned: ZonedTime, [kind, step]: TimeUnit) {
	if (kind === "minute" || kind === "hour") return `${zoned.dayNumber}-${Math.floor(zoned.minuteOfDay / (kind === "hour" ? step * 60 : step))}`;
	// Weeks start on Monday; the epoch day 0 was a Thursday, so shift by 3.
	if (kind === "day") return String(Math.floor((zoned.dayNumber + (step === 7 ? 3 : 0)) / step));
	if (kind === "month") return `${zoned.year}-${Math.floor(zoned.month / step)}`;
	return String(zoned.year);
}

/** Formats a tick: times within a day show the clock, and a tick that starts a new day or year shows that instead. */
function formatTick(time: number, zoned: ZonedTime, previous: ZonedTime | undefined, [kind]: TimeUnit, formats: TimeFormats) {
	const isNewDay = !previous || previous.dayNumber !== zoned.dayNumber;
	const isNewYear = !previous || previous.year !== zoned.year;
	if (kind === "minute" || kind === "hour") return isNewDay ? formats.day.format(time) : formats.time.format(time);
	if (kind === "day") return formats.day.format(time);
	if (kind === "month") return isNewYear ? formats.year.format(time) : formats.month.format(time);
	return formats.year.format(time);
}

/** Picks the candles that get a time tick, using the finest calendar unit whose labels fit in `width`. */
export function getTimeTicks(times: number[], zoned: ZonedTime[], indexes: number[], width: number, minGap: number, timeZone?: string) {
	const formats = getFormats(timeZone);
	for (const [position, unit] of TIME_UNITS.entries()) {
		// A candle starts a bucket when its bucket differs from the candle before it, even one off screen.
		const starts = indexes.filter((index) => index > 0 && getBucket(zoned[index], unit) !== getBucket(zoned[index - 1], unit));
		// If the labels fit, or this is the coarsest unit: use it.
		if (starts.length * minGap <= width || position === TIME_UNITS.length - 1) return starts.map((index) => ({ index, label: formatTick(times[index], zoned[index], zoned[index - 1], unit, formats) }));
	}
	return [];
}

/** A point in plot pixels */
export type Point = [x: number, y: number];

/** One cubic piece of a line from one point to the next; a straight piece puts its controls on its ends */
type Segment = [x0: number, y0: number, c1x: number, c1y: number, c2x: number, c2y: number, x1: number, y1: number];

/** End of a bar that gets the rounded corners */
export type BarEnd = "top" | "bottom" | "left" | "right" | "none";

/** Builds about `count` evenly spaced axis ticks on round numbers that cover `min` to `max`. */
export function getNiceTicks(min: number, max: number, count: number) {
	// If every value is the same: widen the range toward zero, so a flat series still gets an axis.
	if (min === max) {
		if (min > 0) min = 0;
		else if (max < 0) max = 0;
		else max = 1;
	}
	const rawStep = (max - min) / Math.max(1, count);
	const power = 10 ** Math.floor(Math.log10(rawStep));
	const step = [1, 2, 2.5, 5].map((multiple) => multiple * power).find((candidate) => candidate >= rawStep) ?? 10 * power;
	const start = Math.floor(min / step) * step;
	const stepCount = Math.round((Math.ceil(max / step) * step - start) / step);
	// Round each tick, so float steps such as 0.1 + 0.2 print cleanly.
	return Array.from({ length: stepCount + 1 }, (_, index) => Number((start + index * step).toPrecision(12)));
}

/** Splits points into pieces, with monotone curves that never overshoot the data when `curve` is `monotone`. */
function getSegments(points: Point[], curve: "linear" | "monotone"): Segment[] {
	const pieces = points.slice(1).map((point, index) => [points[index], point] as const);
	// If the line is straight or too short to curve: put the controls on the ends.
	if (curve === "linear" || points.length < 3) return pieces.map(([[x0, y0], [x1, y1]]) => [x0, y0, x0, y0, x1, y1, x1, y1]);

	// Fritsch–Carlson tangents: average the neighboring slopes, then limit them so no piece overshoots.
	const slopes = pieces.map(([[x0, y0], [x1, y1]]) => (y1 - y0) / (x1 - x0 || 1));
	const tangents = points.map((_, index) => {
		if (index === 0) return slopes[0];
		if (index === points.length - 1) return slopes[index - 1];
		return slopes[index - 1] * slopes[index] <= 0 ? 0 : (slopes[index - 1] + slopes[index]) / 2;
	});
	for (const [index, slope] of slopes.entries()) {
		// If the piece is flat: flatten both ends, so the curve holds still.
		if (slope === 0) {
			tangents[index] = 0;
			tangents[index + 1] = 0;
			continue;
		}
		const a = tangents[index] / slope;
		const b = tangents[index + 1] / slope;
		const length = a * a + b * b;
		if (length > 9) {
			tangents[index] = (3 / Math.sqrt(length)) * a * slope;
			tangents[index + 1] = (3 / Math.sqrt(length)) * b * slope;
		}
	}
	return pieces.map(([[x0, y0], [x1, y1]], index) => {
		const third = (x1 - x0) / 3;
		return [x0, y0, x0 + third, y0 + tangents[index] * third, x1 - third, y1 - tangents[index + 1] * third, x1, y1];
	});
}

/** Writes pieces as path commands, without the starting move. */
function toCommands(segments: Segment[]) {
	return segments.map(([, , c1x, c1y, c2x, c2y, x1, y1]) => `C${c1x},${c1y} ${c2x},${c2y} ${x1},${y1}`).join("");
}

/** Reverses pieces, so a path can run back along them. */
function reverseSegments(segments: Segment[]): Segment[] {
	return segments.toReversed().map(([x0, y0, c1x, c1y, c2x, c2y, x1, y1]) => [x1, y1, c2x, c2y, c1x, c1y, x0, y0]);
}

/** Builds the path of a line through the points. */
export function getLinePath(points: Point[], curve: "linear" | "monotone") {
	// If there are no points: draw nothing.
	if (!points.length) return "";
	const [[x, y]] = points;
	return `M${x},${y}${toCommands(getSegments(points, curve))}`;
}

/** Builds the path of an area between a top line and a bottom line with matching x positions. */
export function getAreaPath(top: Point[], bottom: Point[], curve: "linear" | "monotone") {
	// If there are no points: draw nothing.
	if (!top.length) return "";
	const [[x, y]] = top;
	const [lastX, lastY] = bottom.at(-1) ?? top[0];
	return `M${x},${y}${toCommands(getSegments(top, curve))}L${lastX},${lastY}${toCommands(reverseSegments(getSegments(bottom, curve)))}Z`;
}

/** Builds a bar path with rounded corners on one end and square corners on the baseline end. */
export function getBarPath(x: number, y: number, width: number, height: number, radius: number, end: BarEnd) {
	const isVertical = end === "top" || end === "bottom";
	// The radius never passes half the bar's thickness or its full length, so short bars stay bars.
	const r = Math.max(0, Math.min(radius, isVertical ? width / 2 : height / 2, isVertical ? height : width));
	const right = x + width;
	const bottom = y + height;
	if (end === "top") return `M${x},${bottom}V${y + r}A${r},${r} 0 0 1 ${x + r},${y}H${right - r}A${r},${r} 0 0 1 ${right},${y + r}V${bottom}Z`;
	if (end === "bottom") return `M${x},${y}H${right}V${bottom - r}A${r},${r} 0 0 1 ${right - r},${bottom}H${x + r}A${r},${r} 0 0 1 ${x},${bottom - r}Z`;
	if (end === "right") return `M${x},${y}H${right - r}A${r},${r} 0 0 1 ${right},${y + r}V${bottom - r}A${r},${r} 0 0 1 ${right - r},${bottom}H${x}Z`;
	if (end === "left") return `M${right},${y}V${bottom}H${x + r}A${r},${r} 0 0 1 ${x},${bottom - r}V${y + r}A${r},${r} 0 0 1 ${x + r},${y}Z`;
	return `M${x},${y}H${right}V${bottom}H${x}Z`;
}

/** Converts an angle in radians, clockwise from the right, and a distance from the center to a point. */
export function getPolarPoint(centerX: number, centerY: number, radius: number, angle: number): Point {
	return [centerX + radius * Math.cos(angle), centerY + radius * Math.sin(angle)];
}

/** Builds a ring slice from `startAngle` clockwise to `endAngle`; an inner radius of 0 draws a pie slice, and `endRadius` rounds only the end corners. */
export function getSectorPath(centerX: number, centerY: number, innerRadius: number, outerRadius: number, startAngle: number, endAngle: number, endRadius = 0) {
	// A full circle cannot be one arc, so stop a hair short of it.
	const sweep = Math.min(Math.max(0, endAngle - startAngle), Math.PI * 2 - 1e-4);
	const end = startAngle + sweep;
	// The corners never round past half the ring's thickness or the arc's length.
	const r = Math.max(0, Math.min(endRadius, (outerRadius - innerRadius) / 2, sweep * outerRadius, innerRadius > 0 ? sweep * innerRadius : Infinity));
	const point = (radius: number, angle: number) => getPolarPoint(centerX, centerY, radius, angle).join(",");
	const outerEnd = end - r / outerRadius;
	const largeOuter = outerEnd - startAngle > Math.PI ? 1 : 0;
	let path = `M${point(outerRadius, startAngle)}A${outerRadius},${outerRadius} 0 ${largeOuter} 1 ${point(outerRadius, outerEnd)}`;
	// Round the end with curves through its true corners.
	path += r > 0 ? `Q${point(outerRadius, end)} ${point(outerRadius - r, end)}` : "";
	// If there is no hole: close through the center, as a pie slice.
	if (innerRadius <= 0) return `${path}L${centerX},${centerY}Z`;
	const innerEnd = end - r / innerRadius;
	const largeInner = innerEnd - startAngle > Math.PI ? 1 : 0;
	path += r > 0 ? `L${point(innerRadius + r, end)}Q${point(innerRadius, end)} ${point(innerRadius, innerEnd)}` : `L${point(innerRadius, end)}`;
	return `${path}A${innerRadius},${innerRadius} 0 ${largeInner} 0 ${point(innerRadius, startAngle)}Z`;
}

/** Reads a field as a number; anything else, such as a missing value, becomes `NaN`. */
export function toNumber(value: unknown) {
	return typeof value === "number" ? value : typeof value === "string" && value.trim() !== "" ? Number(value) : NaN;
}
